const output=path.join(dir,'r3-amiba1-research-payoff-b16-20261119-v1.json'),log=path.join(dir,'r3-amiba1-research-payoff-b16-events-20261119-v1.jsonl');assert(!fs.existsSync(output)&&!fs.existsSync(log));
