function drainKnownResearch(b){for(let guard=0;c.inspect().phase==='awaiting_input';guard++){assert(guard<8,'unexpected research effect loop');const actions=legal();const market=actions.find(a=>a.family==='choose_card'&&a.target?.cardInstanceId==='card-62-0');const trigger=actions.find(a=>a.family==='accept_optional_effect'&&a.target?.cardInstanceId==='alien-amiba-1-2'&&a.target?.ruleId==='amiba1-orange-tech'&&a.target.choiceId.startsWith('confirm:'));if(market){submit(market,b);continue;}if(trigger){submit(trigger,b);continue;}const symbols=actions.filter(a=>a.family==='choose_target'&&a.target?.region==='orange'&&a.target?.symbolId);if(symbols.length){const priority={'symbol_3':4,'symbol_5':2,'symbol_2':0.5,'symbol_1':0.5,'symbol_4':0};symbols.sort((a,b)=>(priority[b.target.symbolId]??-1)-(priority[a.target.symbolId]??-1)||a.actionId.localeCompare(b.actionId));b.symbolSelection={policy:'fixed highest printed score, then data/publicity; blind draw last',target:symbols[0].target};submit(symbols[0],b);continue;}throw Error('unsupported mandatory research choice '+JSON.stringify(actions));}}
