 report.phase='complete';report.limits=['This is a chosen legal future-use witness, not a comparison of optimal full-round plans.','Engine branch pays one credit and one extra setup turn; this paired baseline consumes B16 to fund the same orange1; compare the saved engine result to isolate identical remaining hand.','No unknown card identity selected; the reward card was public before both continuations.'];persist();console.log(JSON.stringify({phase:report.phase,nativeInputs:report.nativeInputs,branches:report.branches.map(b=>({name:b.name,initialValue:b.initial.value.total,afterActivation:b.afterActivation?.value,result:b.result}))}));
